import * as THREE from '../vendor/three.module.js';import {View} from './view.js';import {BODIES} from './architecture.js';import {FaultWorld} from './fault-physics.js';
// Reuse the production builders and render transforms without constructing a WebGL renderer.
// Text annotations are the only omitted objects. They are not physical architecture.
export function geometryView(sim){const v=Object.create(View.prototype);Object.assign(v,{sim,mode:'explore',floor:'all',envelopes:false,routes:false,visibilityCulling:false,container:{clientWidth:1280,clientHeight:720},scene:new THREE.Scene(),camera:new THREE.PerspectiveCamera(),renderer:{render(){},setSize(){}},mats:{},groups:{},roofs:[],shutters:[],doorMeshes:[],bounds:[],labels:[],fixedFloors:[],maskGroups:{},fixedMaskGroups:{},maskKey:'',jointKey:'',walkKey:'',orbit:{yaw:.6,pitch:.7,distance:55,target:new THREE.Vector3(46,0,62)}});v.text=g=>{const m=new THREE.Object3D();m.userData.annotation=true;g.add(m);return m;};for(const[name,c]of Object.entries({wall:'#c8c9bb',concrete:'#949c95',metal:'#435c5b',wood:'#877052',lamp:'#e7dd9c',dark:'#2d4142'}))v.material(name,c);v.buildFacility();BODIES.forEach(b=>v.buildBody(b));v.buildPaths();v.jointGroup=new THREE.Group();v.scene.add(v.jointGroup);v.walkGroup=new THREE.Group();v.scene.add(v.walkGroup);v.marker=new THREE.Object3D();v.scene.add(v.marker);v.render();v.scene.updateMatrixWorld(true);return v;}
export function worldFromView(v){const triangles=[],visualOnly=new Set((v.waterRows??[]).map(r=>r.streaks));v.scene.updateMatrixWorld(true);v.scene.traverse(m=>{if(!m.isMesh||m.userData.annotation||(v.waterSurfaces??[]).includes(m.material))return;let owner=m.userData.owner??'facility';for(let p=m;p;p=p.parent){if(!p.visible||p.userData.annotation||visualOnly.has(p))return;if(p.userData.diagnosticId)owner=p.userData.diagnosticId;}
 const g=m.geometry,positions=g.attributes.position,index=g.index;if(!positions)return;for(let i=0;i<(index?.count??positions.count);i+=3){const points=[0,1,2].map(k=>new THREE.Vector3().fromBufferAttribute(positions,index?index.getX(i+k):i+k).applyMatrix4(m.matrixWorld));const t=new THREE.Triangle(...points);if(t.getArea()<1e-9)continue;t.owner=owner;t.kind=v.sim.positions[owner]&&Math.min(...points.map(p=>p.y))>=v.sim.positions[owner].y+5.5?'roof':'floor';triangles.push(t);}});return new FaultWorld(triangles);}
